90	      creator,
91	      currentUser,
92	      parentPage,
93	      cardWidth,
94	      isArchived,
95	      readonly,
96	      showBlurredContent,
97	      blurred,
98	      openEditor,
99	      toggleBlurVisibility,
100	      openPreview,
101	    ],
102	  );
103	
104	  if (showEditor) {
105	    return (
106	      <MemoEditor
107	        autoFocus
108	        className="mb-2"
109	        cacheKey={`inline-memo-editor-${memoData.name}`}
110	        memo={memoData}
